package com.example.agenticai.api; import com.example.agenticai.agent.SupervisorAgent; import com.example.agenticai.guardrail.GuardrailService; import com.example.agenticai.memory.ConversationMemory; import com.example.agenticai.model.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api") public class AgentController {final SupervisorAgent a;final GuardrailService g;final ConversationMemory m; public AgentController(SupervisorAgent a,GuardrailService g,ConversationMemory m){this.a=a;this.g=g;this.m=m;} @PostMapping("/chat") public ChatResponse chat(@Valid @RequestBody ChatRequest r){String s=r.sessionId()==null||r.sessionId().isBlank()?"default":r.sessionId();String x=g.validate(r.question());return x!=null?new ChatResponse(x,java.util.List.of(),java.util.List.of(),0):a.run(r.question(),s);} @DeleteMapping("/memory/{id}") public String clear(@PathVariable String id){m.clear(id);return "Memory cleared";}}
